var builder = DistributedApplication.CreateBuilder(args);

// Infrastructure Dependencies
var redis = builder.AddRedis("cache");

var postgres = builder.AddPostgres("postgres")
    .WithPgAdmin()
    .AddDatabase("enterprise-nexus-db");

// Backend API Service
var backendApi = builder.AddProject<Projects.EnterpriseNexus_WebApi>("backend-api")
    .WithReference(redis)
    .WithReference(postgres)
    .WithEnvironment("AI__Provider", "AzureOpenAI")
    .WithEnvironment("AI__ModelDeployment", "gpt-4o");

// Document Ingestion Background Worker
builder.AddProject<Projects.EnterpriseNexus_IngestionWorker>("ingestion-worker")
    .WithReference(postgres)
    .WithReference(redis)
    .WaitFor(postgres);

// React 19 Frontend SPA
builder.AddNpmApp("frontend", "../EnterpriseNexus.Frontend", "dev")
    .WithReference(backendApi)
    .WithHttpEndpoint(port: 3000, targetPort: 5173, env: "PORT")
    .PublishAsDockerFile();

builder.Build().Run();
